import React from 'react';import Reveal from './Reveal';import './Experience.css';
const EXPERIENCE=[{company:'CodeEmy Technologies',role:'Business Development Executive Intern',duration:'1 Month',points:['Assisted in client communication and business development activities.','Generated leads and maintained strong client relationships through effective communication.','Collaborated with team members to support daily business operations and improve workflow.']}];
function Experience(){return <section id="experience" className="section experience"><div className="container"><div className="section-header"><Reveal><p className="eyebrow">/ Experience</p><h2 className="section-title">Work Timeline</h2></Reveal></div><div className="timeline">{EXPERIENCE.map((item,i)=><Reveal key={item.company} className="timeline-item" delay={i*100}><div className="timeline-meta">{item.duration}</div><div><h3 className="timeline-company">{item.company}</h3><p className="timeline-role">{item.role}</p><ul className="timeline-points">{item.points.map(p=><li key={p}>{p}</li>)}</ul></div></Reveal>)}</div></div></section>};export default Experience;
